import std/tables

var fibCache = initTable[int, uint64]()

proc fibonacci*(n: int): uint64 =
  if n <= 1:
    return uint64(n)
  if fibCache.hasKey(n):
    return fibCache[n]

  let res = fibonacci(n - 1) + fibonacci(n - 2)
  fibCache[n] = res
  return res

when isMainModule:
  assert fibonacci(10) == 55'u64
  assert fibonacci(50) == 12586269025'u64
  echo "Memoized Fibonacci verified."

import std/tables

proc twoSum*(nums: seq[int], target: int): tuple[idx1, idx2: int] =
  var seen = initTable[int, int]()
  for i, num in nums:
    let complement = target - num
    if seen.hasKey(complement):
      return (seen[complement], i)
    seen[num] = i
  return (-1, -1) # Not found

when isMainModule:
  let indices = twoSum(@[2, 7, 11, 15], 9)
  assert indices == (0, 1)

  let indices2 = twoSum(@[3, 2, 4], 6)
  assert indices2 == (1, 2)
  echo "Two-Sum using table works."

import std/tables

proc firstNonRepeatingChar*(s: string): char =
  var counts = initTable[char, int]()
  for c in s:
    if counts.hasKey(c):
      counts[c] = counts[c] + 1
    else:
      counts[c] = 1

  for c in s:
    if counts[c] == 1:
      return c

  return '\0'

when isMainModule:
  assert firstNonRepeatingChar("nimlang") == 'n'
  assert firstNonRepeatingChar("aabbcc") == '\0'
  assert firstNonRepeatingChar("racecars") == 'e'
  echo "First non-repeating character algorithm successful."

import std/sets

proc intersectAll*(sets: seq[HashSet[int]]): HashSet[int] =
  if sets.len == 0:
    return initHashSet[int]()

  result = sets[0]
  for i in 1 ..< sets.len:
    result = result * sets[i]

when isMainModule:
  let s1 = toHashSet([1, 2, 3, 4])
  let s2 = toHashSet([2, 3, 4, 5])
  let s3 = toHashSet([3, 4, 5, 6])

  let common = intersectAll(@[s1, s2, s3])
  assert common == toHashSet([3, 4])

  let emptyList = newSeq[HashSet[int]]()
  assert intersectAll(emptyList).len == 0
  echo "Multiple set intersection computed correctly."

