proc isProperSubset*[T](a, b: HashSet[T]): bool =
  if a.len >= b.len:
    return false

  for item in a:
    if not b.contains(item):
      return false

  return true

when isMainModule:
  let a = toHashSet([1, 2])
  let b = toHashSet([1, 2, 3])
  let c = toHashSet([1, 2])
  let d = toHashSet([4, 5])

  assert isProperSubset(a, b) == true
  assert isProperSubset(a, c) == false
  assert isProperSubset(d, b) == false
  echo "Proper subset logic verified."

