proc symmetricDifference*(a, b: HashSet[string]): HashSet[string] =
  # Nim provides the -+- operator for symmetric difference
  result = a -+- b

when isMainModule:
  let set1 = toHashSet(["apple", "banana", "cherry"])
  let set2 = toHashSet(["banana", "cherry", "date"])

  let symDiff = symmetricDifference(set1, set2)
  assert symDiff == toHashSet(["apple", "date"])
  echo "Symmetric difference verified."

import std/sets

proc findUniquePairs*(nums: seq[int], target: int): HashSet[tuple[a, b: int]] =
  result = initHashSet[tuple[a, b: int]]()
  var seen = initHashSet[int]()

  for num in nums:
    let complement = target - num
    if seen.contains(complement):
      let a = min(num, complement)
      let b = max(num, complement)
      result.incl((a, b))
    seen.incl(num)

when isMainModule:
  let pairs = findUniquePairs(@[1, 5, 1, 5, 2, 4, 3, 3], 6)
  assert pairs.len == 3
  assert pairs.contains((1, 5))
  assert pairs.contains((2, 4))
  assert pairs.contains((3, 3))
  echo "Unique pairs sum found successfully."

proc merge(left, right: seq[int]): seq[int] =
  result = newSeqOfCap[int](left.len + right.len)
  var i, j = 0

  while i < left.len and j < right.len:
    if left[i] <= right[j]:
      result.add(left[i])
      inc i
    else:
      result.add(right[j])
      inc j

  while i < left.len:
    result.add(left[i])
    inc i
  while j < right.len:
    result.add(right[j])
    inc j

proc mergeSort*(s: seq[int]): seq[int] =
  if s.len <= 1:
    return s

  let mid = s.len div 2
  let left = mergeSort(s[0 ..< mid])
  let right = mergeSort(s[mid .. ^1])

  return merge(left, right)

when isMainModule:
  let nums = @[38, 27, 43, 3, 9, 82, 10]
  let sortedNums = mergeSort(nums)

  assert sortedNums == @[3, 9, 10, 27, 38, 43, 82]
  assert mergeSort(newSeq[int]()) == @[]
  echo "Merge sort verified."

type
  Node*[T] = ref object
    value: T
    left, right: Node[T]

proc searchBST*[T](root: Node[T], target: T): bool =
  if root == nil:
    return false
  if root.value == target:
    return true
  if target < root.value:
    return searchBST(root.left, target)
  else:
    return searchBST(root.right, target)

when isMainModule:
  var root = Node[int](value: 20)
  root.left = Node[int](value: 10)
  root.right = Node[int](value: 30)

  assert searchBST(root, 30) == true
  assert searchBST(root, 10) == true
  assert searchBST(root, 25) == false
  echo "BST search works."

