proc maxDepth*[T](root: Node[T]): int =
  if root == nil:
    return 0
  else:
    let leftDepth = maxDepth(root.left)
    let rightDepth = maxDepth(root.right)
    return 1 + max(leftDepth, rightDepth)

when isMainModule:
