  root.right = Node[int](value: 3)
  root.left.left = Node[int](value: 4)

  assert maxDepth(root) == 3
  assert maxDepth(Node[int](nil)) == 0
  echo "Maximum depth of binary tree found."

import std/deques

type
  Node*[T] = ref object
    value: T
    left, right: Node[T]

proc levelOrder*[T](root: Node[T]): seq[seq[T]] =
  result = @[]
  if root == nil: return

  var queue = initDeque[Node[T]]()
  queue.addLast(root)

  while queue.len > 0:
    var levelSize = queue.len
    var currentLevel = newSeqOfCap[T](levelSize)

    for i in 0 ..< levelSize:
      let node = queue.popFirst()
      currentLevel.add(node.value)

      if node.left != nil: queue.addLast(node.left)
      if node.right != nil: queue.addLast(node.right)

    result.add(currentLevel)

when isMainModule:
  var root = Node[int](value: 3)
  root.left = Node[int](value: 9)
  root.right = Node[int](value: 20)
  root.right.left = Node[int](value: 15)
  root.right.right = Node[int](value: 7)

  let levels = levelOrder(root)
  assert levels == @[@[3], @[9, 20], @[15, 7]]
  echo "Level order traversal correct."

type
  Node* = ref object
    value: int
    left, right: Node

proc lowestCommonAncestor*(root, p, q: Node): Node =
  if root == nil or p == nil or q == nil:
    return nil

  var current = root
  while current != nil:
    if p.value < current.value and q.value < current.value:
      current = current.left
    elif p.value > current.value and q.value > current.value:
      current = current.right
    else:
      return current

  return nil

when isMainModule:
  var root = Node(value: 6)
  let n2 = Node(value: 2)
  let n8 = Node(value: 8)
  root.left = n2
  root.right = n8
  let n0 = Node(value: 0)
  let n4 = Node(value: 4)
  n2.left = n0
  n2.right = n4

  let lca = lowestCommonAncestor(root, n2, n8)
  assert lca == root

  let lca2 = lowestCommonAncestor(root, n2, n4)
  assert lca2 == n2
  echo "LCA in BST verified."

