type
  Graph* = Table[string, seq[string]]

proc bfs*(g: Graph, startNode: string): seq[string] =
  result = @[]
  var visited = initHashSet[string]()
  var queue = initDeque[string]()

  visited.incl(startNode)
  queue.addLast(startNode)

  while queue.len > 0:
    let node = queue.popFirst()
    result.add(node)

    if g.hasKey(node):
      for neighbor in g[node]:
        if not visited.contains(neighbor):
          visited.incl(neighbor)
          queue.addLast(neighbor)

when isMainModule:
  var g = initTable[string, seq[string]]()
  g["A"] = @["B", "C"]
  g["B"] = @["D", "E"]
  g["C"] = @["F"]

  let bfsResult = bfs(g, "A")
  assert bfsResult == @["A", "B", "C", "D", "E", "F"]
  echo "BFS traversal successful."

