type
  Graph* = Table[string, seq[string]]

proc topologicalSort*(g: Graph, vertices: seq[string]): seq[string] =
  var inDegree = initTable[string, int]()
  for v in vertices: inDegree[v] = 0

  for u, neighbors in g.pairs:
    for v in neighbors:
      inDegree[v] = inDegree.getOrDefault(v, 0) + 1

  var queue = initDeque[string]()
  for v in vertices:
    if inDegree[v] == 0:
      queue.addLast(v)

  result = @[]
  while queue.len > 0:
    let u = queue.popFirst()
    result.add(u)

    if g.hasKey(u):
      for v in g[u]:
        inDegree[v] = inDegree[v] - 1
        if inDegree[v] == 0:
          queue.addLast(v)

  if result.len != vertices.len:
    return @[] # Cycle detected

when isMainModule:
  var g = initTable[string, seq[string]]()
  g["5"] = @["2", "0"]
  g["4"] = @["0", "1"]
  g["2"] = @["3"]
  g["3"] = @["1"]
  let vertices = @["0", "1", "2", "3", "4", "5"]

  let order = topologicalSort(g, vertices)
  assert order.len == 6
  # 4 and 5 must come before 0, 1, 2, 3 etc.
  assert order.find("5") < order.find("2")
  assert order.find("4") < order.find("1")
  echo "Topological sort completed."

import std/[tables, deques]

type
  Graph* = Table[string, seq[string]]

proc isBipartite*(g: Graph, vertices: seq[string]): bool =
  var colors = initTable[string, int]()

  for startNode in vertices:
    if not colors.hasKey(startNode):
      var queue = initDeque[string]()
      queue.addLast(startNode)
      colors[startNode] = 0

      while queue.len > 0:
        let u = queue.popFirst()
        let currentColor = colors[u]

        if g.hasKey(u):
          for v in g[u]:
            if not colors.hasKey(v):
              colors[v] = 1 - currentColor
              queue.addLast(v)
            elif colors[v] == currentColor:
              return false

  return true

when isMainModule:
  var gBipartite = initTable[string, seq[string]]()
  gBipartite["A"] = @["B", "D"]
  gBipartite["B"] = @["A", "C"]
  gBipartite["C"] = @["B", "D"]
  gBipartite["D"] = @["A", "C"]
  assert isBipartite(gBipartite, @["A", "B", "C", "D"]) == true

  var gNotBipartite = initTable[string, seq[string]]()
  gNotBipartite["A"] = @["B", "C"]
  gNotBipartite["B"] = @["A", "C"]
  gNotBipartite["C"] = @["A", "B"]
  assert isBipartite(gNotBipartite, @["A", "B", "C"]) == false
  echo "Bipartite check passed."

proc twoSumSorted*(s: seq[int], target: int): tuple[idx1, idx2: int] =
  var left = 0
  var right = s.high

  while left < right:
    let currentSum = s[left] + s[right]
    if currentSum == target:
      return (left, right)
    elif currentSum < target:
      inc left
    else:
      dec right

  return (-1, -1)

when isMainModule:
  let data = @[2, 7, 11, 15]
  assert twoSumSorted(data, 9) == (0, 1)
  assert twoSumSorted(data, 26) == (2, 3)
  assert twoSumSorted(data, 100) == (-1, -1)
  echo "Two-pointer sum algorithm passed."
